// NB-08 · spec: .qa/e2e/specs/nearby.md 1.8 · две роли · меняет данные → в finally оба false.
import { test, expect } from '../../fixtures';
import { openRole, turnOff, meetPair, tapWhenTop, isProfilePatch, dbState, callRpc, expectInRecent, shareSwitch, consentTitle, enableBtn, listTitle, card, NAME } from './nearby-helpers';

test.use({ browserName: 'webkit' });

test.describe('היו כאן — משתמשים שהיו בקרבת מקום', () => {
  test.describe.configure({ timeout: 240_000 });
  test('выключение тумблером — диалог, «ביטול» без изменений, «כיבוי» стирает историю и снова просит согласие; у другого пропадает @iphone @data (#ab0123 #ee51bb #67c751)', async ({ browser }) => {
    const reg1 = await openRole(browser, 'reg1');
    const reg2 = await openRole(browser, 'reg2');
    try {
      await meetPair(reg1, reg2);
      const p = reg1.page;
      const patches: string[] = [];
      p.on('response', (r) => { if (isProfilePatch(r)) patches.push(r.request().postData() ?? ''); });

      await tapWhenTop(p, shareSwitch(p));
      const dlg = p.getByRole('dialog');
      await expect(dlg.getByText('לכבות את שיתוף המיקום?')).toBeVisible();
      await expect(dlg.getByRole('button', { name: 'כיבוי שיתוף מיקום' })).toBeVisible();
      await dlg.getByRole('button', { name: 'ביטול' }).click();
      await expect(dlg).toHaveCount(0);
      await expect(card(p, NAME.reg2)).toBeVisible();
      expect(patches, '«ביטול» не отправляет PATCH').toEqual([]);

      await tapWhenTop(p, shareSwitch(p));
      const patch = p.waitForResponse(isProfilePatch);
      await p.getByRole('dialog').getByRole('button', { name: 'כיבוי שיתוף מיקום' }).click();
      const res = await patch;
      expect(res.ok()).toBeTruthy();
      expect(res.request().postDataJSON()).toMatchObject({ share_location: false });
      await expect(consentTitle(p)).toBeVisible();
      await expect(enableBtn(p)).toBeVisible();
      await expect(listTitle(p)).toHaveCount(0);

      expect(await dbState(reg1)).toEqual({ nearby_opt_in: false, share_location: false });
      expect(await callRpc(reg1, 'nearby_recent'), 'история reg1 стёрта').toEqual([]);
      expect(await callRpc(reg1, 'nearby_places')).toEqual([]);
      await expect(consentTitle(p)).toBeVisible(); // после перезагрузки снова согласие

      // У reg2 карточка reg1 пропадает.
      await expectInRecent(reg2.page, reg1.id, false);
      await expect(card(reg2.page, NAME.reg1)).toHaveCount(0);
    } finally {
      await turnOff(reg1);
      await turnOff(reg2);
      await reg1.ctx.close();
      await reg2.ctx.close();
    }
  });
});
